若 int a[10];，则数组 a 的合法下标范围是（ ）。

以下第16-19题基于以下程序：

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    int ans = 0;
    for (int i = 1; i <= n; i++) {
        int x = i;
        while (x > 0) {
            ans += x % 10;
            x /= 10;
        }
    }
    cout << ans << endl;
    return 0;
}
```

当输入为 5 时，输出为（ ）。

以下第20-23题基于以下程序：

```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    int best = 1, len = 1;
    for (int i = 1; i < n; i++) {
        if (a[i] > a[i - 1]) len++;
        else len = 1;
        best = max(best, len);
    }
    cout << best << endl;
    return 0;
}
```

