```
7
1 2 2 3 5 4 6
```

输出为（ ）。

以下第24-27题基于以下程序：

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n + 1);
    vector<int> deg(n + 1, 0);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        deg[v]++;
    }

    priority_queue<int, vector<int>, greater<int>> q;
    for (int i = 1; i <= n; i++)
        if (deg[i] == 0) q.push(i);

    vector<int> ans;
    while (!q.empty()) {
        int u = q.top();
        q.pop();
        ans.push_back(u);
        for (int v : g[u]) {
            deg[v]--;
            if (deg[v] == 0) q.push(v);
        }
    }

    if ((int)ans.size() < n) cout << -1 << endl;
    else {
        for (int x : ans) cout << x << ' ';
        cout << endl;
    }
    return 0;
}
```

