给定一个 n 行 m 列的网格，字符 . 表示可以通过，字符 # 表示障碍。程序计算从左上角 (0, 0) 到右下角 (n − 1, m − 1) 最少需要走多少步。每一步可以向上、下、左、右移动一格；若无法到达，输出 −1。保证起点和终点不是障碍。

以下第33-37题基于以下程序：

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> s(n);
    for (auto &row : s) cin >> row;

    vector<vector<int>> dis(n, vector<int>(m, -1));
    queue<pair<int, int>> q;
    q.push({0, 0});
    ____①____;

    int dx[4] = {1, -1, 0, 0};
    int dy[4] = {0, 0, 1, -1};

    while (____②____) {
        auto [x, y] = q.front();
        ____③____;
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
            if (s[nx][ny] == '#') continue;
            if (____④____) continue;
            dis[nx][ny] = ____⑤____;
            q.push({nx, ny});
        }
    }

    cout << dis[n - 1][m - 1] << endl;
    return 0;
}
```

①处应填（ ）。
